const std = @import("std"); const cpu_mask = @import("cpu_mask"); const bpf_type_names = @import("bpf_type_names"); const logging = @import("logging"); const pin_path = @import("pin_path"); const perf_buffer_poll = @import("perf_buffer_poll"); const Gap = struct { id: []const u8, status: []const u8, kind: []const u8, zigux_destination: []const u8, why_now: []const u8, }; const Manifest = struct { lane_key: []const u8, phase: []const u8, surveyed_commit: []const u8, gaps: []const Gap, }; const LegacySegment = struct { id: []const u8, slug: []const u8, status: []const u8, kind: []const u8, zigux_destination: []const u8, why_now: []const u8, }; const LegacyManifest = struct { lane_key: []const u8, phase: []const u8, surveyed_commit: []const u8, segments: []const LegacySegment, }; fn pathExists(io: std.Io, path: []const u8) !bool { std.Io.Dir.cwd().access(io, path, .{}) catch |err| switch (err) { error.FileNotFound => return false, else => return err, }; return true; } test "phase12 libbpf reviewability gate matches the current zigux_segments file state" { var io_instance: std.Io.Threaded = .init(std.testing.allocator, .{}); defer io_instance.deinit(); const manifest_json = try std.Io.Dir.cwd().readFileAlloc( io_instance.io(), "zigux/tests/phase12_libbpf_manifest.json", std.testing.allocator, .limited(32 * 1024), ); defer std.testing.allocator.free(manifest_json); const parsed = try std.json.parseFromSlice(Manifest, std.testing.allocator, manifest_json, .{ .ignore_unknown_fields = true, }); defer parsed.deinit(); const manifest = parsed.value; try std.testing.expectEqualStrings("P12-L13", manifest.lane_key); try std.testing.expectEqualStrings("Phase 12", manifest.phase); var saw_landed_manifest = false; var saw_landed_type_names = false; var saw_landed_cpu_mask = false; var saw_landed_logging = false; var saw_landed_pin_path = false; var saw_blocked_skeleton = false; var saw_blocked_object_loader = false; var saw_blocked_relocation = false; for (manifest.gaps) |gap| { if (!std.mem.startsWith(u8, gap.zigux_destination, "tools/lib/bpf/zigux_segments/")) { continue; } const exists = try pathExists(io_instance.io(), gap.zigux_destination); if (std.mem.eql(u8, gap.status, "starter_landed")) { try std.testing.expect(exists); } else if (std.mem.eql(u8, gap.status, "ready_next") or std.mem.eql(u8, gap.status, "blocked_on_object_model") or std.mem.eql(u8, gap.status, "deferred_high_risk")) { try std.testing.expect(!exists); } if (std.mem.eql(u8, gap.id, "phase12-libbpf-segment-manifest-foundation")) { saw_landed_manifest = true; try std.testing.expect(exists); } if (std.mem.eql(u8, gap.id, "phase12-libbpf-type-name-helper-foundation")) { saw_landed_type_names = true; try std.testing.expect(exists); } if (std.mem.eql(u8, gap.id, "phase12-libbpf-cpu-mask-helper-foundation")) { saw_landed_cpu_mask = true; try std.testing.expect(exists); } if (std.mem.eql(u8, gap.id, "phase12-libbpf-logging-helper-foundation")) { saw_landed_logging = true; try std.testing.expect(exists); } if (std.mem.eql(u8, gap.id, "phase12-libbpf-pin-path-helper-foundation")) { saw_landed_pin_path = true; try std.testing.expect(exists); } if (std.mem.eql(u8, gap.id, "phase12-libbpf-skeleton-population")) { saw_blocked_skeleton = true; try std.testing.expect(!exists); } if (std.mem.eql(u8, gap.id, "phase12-libbpf-object-loader-and-program-load")) { saw_blocked_object_loader = true; try std.testing.expect(!exists); } if (std.mem.eql(u8, gap.id, "phase12-libbpf-btf-relocation-and-program-load")) { saw_blocked_relocation = true; try std.testing.expect(!exists); } } try std.testing.expect(saw_landed_manifest); try std.testing.expect(saw_landed_type_names); try std.testing.expect(saw_landed_cpu_mask); try std.testing.expect(saw_landed_logging); try std.testing.expect(saw_landed_pin_path); try std.testing.expect(saw_blocked_skeleton); try std.testing.expect(saw_blocked_object_loader); try std.testing.expect(saw_blocked_relocation); } test "phase12 libbpf reviewability gate still compiles the landed helper foundations" { const parsed = try cpu_mask.parseCpuMaskString(std.testing.allocator, "0-1,3"); defer parsed.deinit(std.testing.allocator); var path_buffer: [64]u8 = undefined; var error_buffer: [64]u8 = undefined; const ready_buffers = [_]perf_buffer_poll.BufferObservation{ .{ .ready = true }, .{ .error_code = -11 }, }; try std.testing.expectEqual(@as(usize, 3), cpu_mask.countPossibleCpus(parsed.values)); try std.testing.expectEqualStrings("xdp", bpf_type_names.libbpfBpfAttachTypeStr(37).?); try std.testing.expectEqualStrings("ringbuf", bpf_type_names.libbpfBpfMapTypeStr(27).?); try std.testing.expectEqualStrings("v1.8", logging.libbpfVersionString()); try std.testing.expectEqualStrings( "Internal error in libbpf", try logging.formatErrorString(&error_buffer, -4004), ); try std.testing.expectEqualStrings( "/sys/fs/bpf/demo_map", try pin_path.buildValidatedSanitizedMapPinPath(&path_buffer, null, "demo.map"), ); try std.testing.expectError( error.InvalidName, pin_path.buildValidatedSanitizedMapPinPath(&path_buffer, null, "demo/map"), ); try std.testing.expectError( error.InvalidRootPath, pin_path.buildValidatedSanitizedMapPinPath(&path_buffer, "tmp/bpf", "demo.map"), ); try std.testing.expectEqualDeep( perf_buffer_poll.WaitObservation{ .ready_events = 2 }, perf_buffer_poll.classifyObservedWaitResult(2), ); const poll_summary = try perf_buffer_poll.summarizePoll(7, .{ .ready_events = 2 }, &ready_buffers); try std.testing.expectEqual(perf_buffer_poll.WaitClass.bounded, poll_summary.wait_class); try std.testing.expectEqual(perf_buffer_poll.PollOutcome.ready, poll_summary.outcome); try std.testing.expectEqual(@as(usize, 1), poll_summary.ready_count); try std.testing.expectEqual(@as(?i32, -11), poll_summary.first_error); } test "phase12 libbpf reviewability gate cross-checks the legacy segment catalog" { var io_instance: std.Io.Threaded = .init(std.testing.allocator, .{}); defer io_instance.deinit(); const manifest_json = try std.Io.Dir.cwd().readFileAlloc( io_instance.io(), "tools/lib/bpf/zigux_segments/manifest.json", std.testing.allocator, .limited(32 * 1024), ); defer std.testing.allocator.free(manifest_json); const parsed = try std.json.parseFromSlice(LegacyManifest, std.testing.allocator, manifest_json, .{ .ignore_unknown_fields = true, }); defer parsed.deinit(); const manifest = parsed.value; try std.testing.expectEqualStrings("P8-L15", manifest.lane_key); try std.testing.expectEqualStrings("Phase 8", manifest.phase); var saw_logging = false; var saw_pin_path = false; var saw_cpu_mask = false; var saw_perf_buffer_poll = false; var saw_skeleton = false; var saw_object_loader = false; var saw_relocation = false; for (manifest.segments) |segment| { const exists = try pathExists(io_instance.io(), segment.zigux_destination); if (std.mem.eql(u8, segment.slug, "logging-version-and-errno")) { saw_logging = true; try std.testing.expectEqualStrings("starter_landed", segment.status); try std.testing.expect(exists); } if (std.mem.eql(u8, segment.slug, "pin-path-helpers")) { saw_pin_path = true; try std.testing.expectEqualStrings("starter_landed", segment.status); try std.testing.expect(exists); } if (std.mem.eql(u8, segment.slug, "cpu-mask-parsing")) { saw_cpu_mask = true; try std.testing.expectEqualStrings("starter_landed", segment.status); try std.testing.expect(exists); } if (std.mem.eql(u8, segment.slug, "perf-buffer-poll-bookkeeping")) { saw_perf_buffer_poll = true; try std.testing.expectEqualStrings("starter_landed", segment.status); try std.testing.expect(exists); } if (std.mem.eql(u8, segment.slug, "skeleton-population")) { saw_skeleton = true; try std.testing.expectEqualStrings("blocked_on_object_model", segment.status); try std.testing.expect(!exists); } if (std.mem.eql(u8, segment.slug, "object-and-elf-loader")) { saw_object_loader = true; try std.testing.expectEqualStrings("deferred_high_risk", segment.status); try std.testing.expect(!exists); } if (std.mem.eql(u8, segment.slug, "btf-relocation-and-program-load")) { saw_relocation = true; try std.testing.expectEqualStrings("deferred_high_risk", segment.status); try std.testing.expect(!exists); } } try std.testing.expect(saw_logging); try std.testing.expect(saw_pin_path); try std.testing.expect(saw_cpu_mask); try std.testing.expect(saw_perf_buffer_poll); try std.testing.expect(saw_skeleton); try std.testing.expect(saw_object_loader); try std.testing.expect(saw_relocation); }